INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李从珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：李从珂。", "biography": null, "status": "draft", "id": "0a45ab01-e475-5d82-9a76-16d916af5abd"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "徐温", "aliases": ["徐溫"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。", "biography": null, "status": "draft", "id": "d3682e36-8a8e-5558-8399-51a71c81330f"}, {"name": "李氏（徐知诰尊奉的母亲）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐知诰尊奉的母亲，原称明德太妃。937年被追尊为王太后。此段没有说明其具体家世，亲属关系仍需补证。", "biography": null, "status": "draft", "id": "42a76ebb-3425-5bce-a2eb-3257f01a1017"}, {"name": "张从宾", "aliases": ["張從賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张从宾，侍卫步军都指挥使、忠正节度使。", "biography": null, "status": "draft", "id": "9a3c8e19-d709-5a20-b9dd-ef00849d161d"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "皎公羡", "aliases": ["皎公羨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "交州将领。《资治通鉴》记载他在937年杀死安南节度使杨廷艺并取代其职务。", "biography": null, "status": "draft", "id": "77668d4d-1def-5fe2-b80d-d256a88e8e1f"}, {"name": "杨廷艺", "aliases": ["楊廷藝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨廷艺，爱州将、养假子谋复交州者。", "biography": null, "status": "draft", "id": "ab60ef4d-6704-510d-bc6a-4c62aa871399"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "钱弘僔", "aliases": ["弘僔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越王钱元瓘的儿子。937年四月被立为世子。", "biography": null, "status": "draft", "id": "b277fec5-6d3f-50f1-9151-ce20879f41b3"}, {"name": "曹仲达", "aliases": ["曹仲達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：曹仲达，处州刺史、权知政事者。", "biography": null, "status": "draft", "id": "510a0a94-ad3f-53ed-bcbc-04bd2a897461"}, {"name": "沈崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：沈崧，浙西营田副使、领择能院者。", "biography": null, "status": "draft", "id": "7fd696f3-988d-5ad6-ad0a-d3ff960b8119"}, {"name": "皮光业", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：皮光业。", "biography": null, "status": "draft", "id": "3483a251-09ee-5344-8902-de110ccbd033"}, {"name": "林鼎", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越官员。937年以镇海节度判官身份掌管教令。", "biography": null, "status": "draft", "id": "f7c11336-2f57-5c43-9ea1-538c76c4b27d"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "张昭（五代宋初）", "aliases": ["张昭远", "張昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：张昭（五代宋初），河间推官、劝表并赞志者。", "biography": null, "status": "draft", "id": "0f1b47dc-df4b-5258-91b3-463432d576b7"}, {"name": "娄继英", "aliases": ["婁繼英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光二年条所见人物：娄继英。", "biography": null, "status": "draft", "id": "f6c6be57-cfd2-54e0-a3d3-f6de4e943c92"}, {"name": "朱友贞", "aliases": ["朱锽", "朱瑱", "均王", "梁末帝"], "era": "五代十国", "birth_year": null, "death_year": 923, "description": "后梁末帝。913年在大梁即位，923年唐军逼近时命皇甫麟杀死自己。", "biography": "后梁末帝。913年在大梁即位，923年唐军逼近时命皇甫麟杀死自己。", "status": "draft", "id": "592627e4-8841-5cca-a79b-782c37765037"}, {"name": "徐景迁", "aliases": ["徐景遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景迁，原牙内马步都指挥使海州团练使、留江都辅政者。", "biography": null, "status": "draft", "id": "17d67985-b1cf-561c-9df9-fcce2c1a5e0d"}]'::jsonb)
